//! Source-footprint fallback for unloaded detailed mesh cells.
//! Never replace real concave buildings with axis-aligned bounding boxes:
//! a bounding box can fill streets, courtyard holes, and neighboring roofs.
//! Geometry is generated by the same authoritative building and DEM code
//! as the detailed renderer, but keeps no far-away road/detail chunk buffers.
use crate::{Building,City,Point};
use crate::chunk_mesh::{append_part,DrawBatch,GpuVertex,SceneLayer};
use crate::geometry::{HeightPolicy,Mesh};
use crate::streaming::ChunkKey;
use crate::terrain::TerrainGrid;
use std::collections::BTreeMap;

#[derive(Default)]
pub struct FarMassing {
    pub vertices:Vec<GpuVertex>,
    pub indices:Vec<u32>,
    /// Whole-building source-owner ranges. Each detailed cell replaces its
    /// corresponding far geometry atomically, never as a separate overlap.
    pub cells:Vec<(ChunkKey,DrawBatch)>,
}

fn owner(building:&Building)->Option<ChunkKey>{
    let ring=building.polygons.first()?.rings.first()?;
    if ring.is_empty(){return None;}
    let x=ring.iter().map(|p|p.x).sum::<f64>()/ring.len() as f64;
    let z=ring.iter().map(|p|p.z).sum::<f64>()/ring.len() as f64;
    if !x.is_finite()||!z.is_finite(){return None;}
    Some(ChunkKey::at(Point{x,z}))
}

/// Use the exact same planar footprint, holes, clearance and terrain
/// foundation as the near building. Low memory mode limits detailed *cells*;
/// it must not invent rectangles covering source-empty land.
fn actual_footprint_mesh(building:&Building,city:&City,terrain:&TerrainGrid)
    ->Option<Mesh>{
    let single=City{
        schema_version:city.schema_version,
        region:city.region.clone(),
        provenance:Vec::new(),
        streets:Vec::new(),
        buildings:vec![building.clone()],
    };
    let (mut mesh,report)=terrain.mesh_buildings(&single,HeightPolicy::default()).ok()?;
    if report.buildings_meshed!=1||mesh.indices.is_empty(){return None;}
    // The simplified far pass uses one neutral city color, not landmark
    // decals, road ribbons or per-building classification surfaces.
    mesh.vertices.shrink_to_fit();
    Some(mesh)
}

pub fn build_far_massing(city:&City,terrain:&TerrainGrid)
    ->Result<FarMassing,String>{
    terrain.validate(&city.region)?;
    let mut by_cell:BTreeMap<ChunkKey,Vec<Mesh>>=BTreeMap::new();
    for building in &city.buildings {
        let Some(key)=owner(building) else{continue;};
        if let Some(mesh)=actual_footprint_mesh(building,city,terrain) {
            by_cell.entry(key).or_default().push(mesh);
        }
    }
    let mut out=FarMassing::default();
    for (key,meshes) in by_cell {
        let first=u32::try_from(out.indices.len())
            .map_err(|_|"distant skyline index count exceeded u32")?;
        for mesh in meshes {
            append_part(&mesh,[0.71,0.76,0.81],&mut out.vertices,&mut out.indices)?;
        }
        let end=u32::try_from(out.indices.len())
            .map_err(|_|"distant skyline index count exceeded u32")?;
        if end>first {
            out.cells.push((key,DrawBatch{
                layer:SceneLayer::Buildings,first_index:first,count:end-first
            }));
        }
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Polygon;

    fn building(id:&str,rings:Vec<Vec<Point>>)->Building{
        Building{
            source_id:id.into(),name:None,height_m:Some(22.0),
            levels:None,min_height_m:None,min_floor:None,parts:vec![],
            polygons:vec![Polygon{rings}],
        }
    }
    #[test]
    fn same_chunk_ownership_as_detailed_mesh(){
        let b=building("b",vec![vec![
            Point{x:1.,z:1.},Point{x:12.,z:1.},
            Point{x:12.,z:8.},Point{x:1.,z:8.},
        ]]);
        assert_eq!(owner(&b),Some(crate::streaming::ChunkKey::at(
            Point{x:6.5,z:4.5})));
    }
    #[test]
    fn concave_roof_never_fills_the_empty_bounding_box_corner(){
        let l_shape=building("L",vec![vec![
            Point{x:0.,z:0.},Point{x:4.,z:0.},
            Point{x:4.,z:1.},Point{x:1.,z:1.},
            Point{x:1.,z:4.},Point{x:0.,z:4.},
        ]]);
        let mesh=crate::geometry::mesh_building(&l_shape,HeightPolicy::default())
            .unwrap();
        let mut roof_area=0.0f64;
        for tri in mesh.indices.chunks_exact(3){
            let pts=[mesh.vertices[tri[0] as usize].position,
                mesh.vertices[tri[1] as usize].position,
                mesh.vertices[tri[2] as usize].position];
            if pts.iter().all(|p|(p[1]-22.).abs()<0.001){
                let a=pts[0];let b=pts[1];let c=pts[2];
                let area=((b[0]-a[0])*(c[2]-a[2])-
                    (b[2]-a[2])*(c[0]-a[0])).abs()*0.5;
                roof_area+=area as f64;
                let x=(a[0]+b[0]+c[0])/3.;
                let z=(a[2]+b[2]+c[2])/3.;
                assert!(x<=1.001||z<=1.001,
                    "low-LOD roof must not fill empty L-shaped notch: {x},{z}");
            }
        }
        assert!((roof_area-7.0).abs()<0.001,
            "actual footprint roof must have area 7, not 16: {roof_area}");
    }
    #[test]
    fn courtyard_roof_area_stays_open(){
        let b=building("courtyard",vec![
            vec![Point{x:0.,z:0.},Point{x:8.,z:0.},
                 Point{x:8.,z:8.},Point{x:0.,z:8.}],
            vec![Point{x:2.,z:2.},Point{x:2.,z:6.},
                 Point{x:6.,z:6.},Point{x:6.,z:2.}],
        ]);
        let mesh=crate::geometry::mesh_building(&b,HeightPolicy::default()).unwrap();
        let area=mesh.indices.chunks_exact(3).filter_map(|tri|{
            let [a,b,c]=[mesh.vertices[tri[0] as usize].position,
                mesh.vertices[tri[1] as usize].position,
                mesh.vertices[tri[2] as usize].position];
            ((a[1]-22.).abs()<0.001&&(b[1]-22.).abs()<0.001&&
              (c[1]-22.).abs()<0.001).then_some(
                  ((b[0]-a[0])*(c[2]-a[2])-
                   (b[2]-a[2])*(c[0]-a[0])).abs()*0.5)
        }).sum::<f32>();
        assert!((area-48.).abs()<0.001,
            "courtyard must remain empty instead of becoming a full box: {area}");
    }
}
